import http from 'http';
import fs from 'fs';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar from 'chokidar';
import { parseMarkdownFiles } from './parser';
import { generateSite } from './generator';

export interface ServeOptions {
  content: string;
  output: string;
  templates: string;
  port: number;
}

function rebuild(content: string, output: string, templates: string): number {
  const pages = parseMarkdownFiles(content);
  generateSite(pages, output, templates);
  return pages.length;
}

function getMimeType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  const mimes: Record<string, string> = {
    '.html': 'text/html',
    '.css': 'text/css',
    '.js': 'application/javascript',
    '.json': 'application/json',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.gif': 'image/gif',
    '.svg': 'image/svg+xml',
  };
  return mimes[ext] || 'application/octet-stream';
}

function injectLiveReload(html: string, port: number): string {
  const script = `<script>
(function() {
  var ws = new WebSocket('ws://localhost:${port}');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') {
      location.reload();
    }
  };
})();
</script>`;
  return html.replace('</body>', script + '\n</body>');
}

export function createServer(options: ServeOptions): http.Server {
  const { content, output, templates, port } = options;
  const resolvedOutput = path.resolve(output);

  rebuild(content, output, templates);

  const server = http.createServer((req, res) => {
    const url = req.url || '/';
    const sanitized = path.normalize(url).replace(/^(\.\.[/\\])+/, '');
    const relativePath = sanitized.replace(/^[/\\]+/, '');
    const filePath = relativePath
      ? path.join(resolvedOutput, relativePath)
      : path.join(resolvedOutput, 'index.html');

    try {
      if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
        res.writeHead(404);
        res.end('Not found');
        return;
      }

      const ext = path.extname(filePath).toLowerCase();
      const content = fs.readFileSync(filePath);

      if (ext === '.html') {
        const html = injectLiveReload(content.toString('utf-8'), port);
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(html);
      } else {
        res.writeHead(200, { 'Content-Type': getMimeType(filePath) });
        res.end(content);
      }
    } catch {
      res.writeHead(500);
      res.end('Internal server error');
    }
  });

  const wss = new WebSocketServer({ server });

  const resolvedContent = path.resolve(content);
  const resolvedTemplates = path.resolve(templates);

  const watcher = chokidar.watch([resolvedContent, resolvedTemplates], {
    ignoreInitial: true,
  });

  watcher.on('all', () => {
    const count = rebuild(content, output, templates);
    wss.clients.forEach((client) => {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    });
  });

  return server;
}

export function serve(options: ServeOptions): http.Server {
  const server = createServer(options);
  server.listen(options.port, () => {
    console.log(`Dev server running at http://localhost:${options.port}`);
  });
  return server;
}

#!/usr/bin/env node

import { parseMarkdownFiles, generateSite } from './index';
import { serve } from './server';

interface CliOptions {
  content: string;
  output: string;
  templates: string;
  port: number;
}

function parseArgs(args: string[]): CliOptions {
  const options: CliOptions = { content: './content', output: './dist', templates: './templates', port: 3000 };

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--content' && i + 1 < args.length) {
      options.content = args[i + 1];
      i++;
    } else if (args[i] === '--output' && i + 1 < args.length) {
      options.output = args[i + 1];
      i++;
    } else if (args[i] === '--templates' && i + 1 < args.length) {
      options.templates = args[i + 1];
      i++;
    } else if (args[i] === '--port' && i + 1 < args.length) {
      options.port = parseInt(args[i + 1], 10) || 3000;
      i++;
    }
  }

  return options;
}

const args = process.argv.slice(2);

if (args.length === 0 || (args[0] !== 'build' && args[0] !== 'serve')) {
  console.error('Usage: ssg build|serve [--content <dir>] [--output <dir>] [--templates <dir>] [--port <port>]');
  process.exit(1);
}

const options = parseArgs(args.slice(1));

if (args[0] === 'build') {
  const pages = parseMarkdownFiles(options.content);
  generateSite(pages, options.output, options.templates);
  console.log(`Generated ${pages.length} page(s) in ${options.output}`);
} else if (args[0] === 'serve') {
  serve(options);
}

